PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS users(id TEXT PRIMARY KEY,email TEXT UNIQUE NOT NULL,created_at INTEGER NOT NULL DEFAULT(unixepoch()));
CREATE TABLE IF NOT EXISTS subscriptions(id TEXT PRIMARY KEY,user_id TEXT NOT NULL,plan_tier TEXT NOT NULL CHECK(plan_tier IN ('FREE','PRO','STUDIO')),status TEXT NOT NULL CHECK(status IN ('ACTIVE','EXPIRED','SUSPENDED')),char_limit INTEGER NOT NULL,current_period_start INTEGER NOT NULL,current_period_end INTEGER NOT NULL,FOREIGN KEY(user_id) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS installations(id TEXT PRIMARY KEY,user_id TEXT NOT NULL,site_url TEXT NOT NULL,created_at INTEGER NOT NULL DEFAULT(unixepoch()),FOREIGN KEY(user_id) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS paired_browsers(id TEXT PRIMARY KEY,installation_id TEXT NOT NULL,session_token_hash TEXT,last_seen_at INTEGER,created_at INTEGER NOT NULL DEFAULT(unixepoch()),FOREIGN KEY(installation_id) REFERENCES installations(id));
CREATE TABLE IF NOT EXISTS quota_periods(id TEXT PRIMARY KEY,user_id TEXT NOT NULL,period_start INTEGER NOT NULL,period_end INTEGER NOT NULL,char_limit INTEGER NOT NULL,reserved_chars INTEGER NOT NULL DEFAULT 0,committed_chars INTEGER NOT NULL DEFAULT 0,FOREIGN KEY(user_id) REFERENCES users(id),UNIQUE(user_id,period_start,period_end));
CREATE TABLE IF NOT EXISTS quota_ledger(id TEXT PRIMARY KEY,user_id TEXT NOT NULL,job_id TEXT UNIQUE NOT NULL,reserved_chars INTEGER NOT NULL,committed_chars INTEGER NOT NULL DEFAULT 0,status TEXT NOT NULL CHECK(status IN ('RESERVED','COMMITTED','REFUNDED')),lease_expires_at INTEGER NOT NULL,created_at INTEGER NOT NULL DEFAULT(unixepoch()),FOREIGN KEY(user_id) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS jobs(id TEXT PRIMARY KEY,user_id TEXT NOT NULL,installation_id TEXT,browser_id TEXT,idempotency_key TEXT NOT NULL,status TEXT NOT NULL CHECK(status IN ('QUEUED','CLAIMED','AUTOMATING','UPLOADING','READY','FAILED','TIMED_OUT')),text_payload TEXT NOT NULL,target_voice TEXT NOT NULL,char_count INTEGER NOT NULL,storage_object_key TEXT,audio_duration_sec REAL,audio_sha256 TEXT,error_code TEXT,last_heartbeat_at INTEGER,created_at INTEGER NOT NULL DEFAULT(unixepoch()),updated_at INTEGER NOT NULL DEFAULT(unixepoch()),FOREIGN KEY(user_id) REFERENCES users(id),FOREIGN KEY(installation_id) REFERENCES installations(id),UNIQUE(user_id,idempotency_key));
CREATE INDEX IF NOT EXISTS idx_jobs_status ON jobs(status);
CREATE INDEX IF NOT EXISTS idx_jobs_browser_status ON jobs(browser_id,status);
CREATE INDEX IF NOT EXISTS idx_quota_ledger_user_status ON quota_ledger(user_id,status);
CREATE INDEX IF NOT EXISTS idx_quota_ledger_lease ON quota_ledger(lease_expires_at);
